const SLOT_COUNT = 16;
const slots = { 3: { primary: "cache-a", replica: "cache-b" } };
const migrating = new Set([3]);
function hashKey(key) {
  return [...key].reduce((h, c) => h + c.charCodeAt(0), 0) >>> 0;
}
function route(key, localNode = "cache-a") {
  const keyHash = hashKey(key);
  const slot = keyHash % SLOT_COUNT;
  const owner = slots[slot];
  if (!owner) throw new Error("unassigned slot");
  if (migrating.has(slot)) {
    const target = owner.replica;
    return { node: target, redirect: localNode !== target, target, migration: "forward-to-replica" };
  }
  const target = owner.primary;
  return { node: target, redirect: localNode !== target, target };
}

